domain commerce.order

import identity.user

@desc("Current order lifecycle status")
pub enum OrderStatus {
    PENDING
    PAID
    CANCELLED
}

pub data Page<TItem> {
    items: list<TItem>
    nextToken: string?
}

pub data OrderLine {
    productId: uuid
    quantity: int
    unitPrice: decimal
}

pub data Order {
    id: uuid
    customer: user.UserSummary
    status: OrderStatus
    lines: list<OrderLine>
    attributes: map<string, string>
    receipt: binary?
}

pub data OrderPage {
    page: Page<Order>
}

config CheckoutConfig eternal {
    timeout: duration
    supportedCurrencies: list<string>
    retryLimitByRegion: map<string, int>
}

domain commerce.order

@desc("Queries and commands for customer orders")
pub service OrderService {
    for CustomerActor via client
    auth
    require any(Order:read, user.User:read)

    method list {
        input {
            pageSize: int
            nextToken: string?
        }
        output OrderPage
    }

    method cancel {
        require all(
            Order:cancel,
            Order:cancel:ownedByCaller(orderId),
            Order:read:exists(orderId)
        )

        input {
            orderId: uuid
        }
        output Order
    }
}

