package core

import (
	"encoding/json"
	"math/rand"
	"reflect"
	"testing"

	"github.com/google/uuid"
	"github.com/shopspring/decimal"

	order "example.com/yorun/demo/order"
	identitypub "example.com/yorun/demo/identitypub"
	"go.yorun.ai/vine/core/skel"
)

// 这些性质测试是 Lean 证明的「验证回流」：lean/Proofs/OrderCore.lean 中
// 已经被 kernel 证明的性质，在这里以固定种子随机化 + 穷举的方式在
// Go 参考实现上执行。证明保证规范自洽；测试守护实现不漂移。
//
// 随机生成器显式构造每个字段（skel.Decimal 内嵌非导出字段，无法用
// testing/quick 反射生成）；种子固定，失败可复现。

const iterations = 300

// seed 返回每个性质独立的可复现种子。
func seed(t *testing.T) int64 {
	return int64(20260827<<8) | int64(len(t.Name())&0xff)
}

func randomUUID(rng *rand.Rand) skel.UUID {
	var bytes [16]byte
	for i := range bytes {
		bytes[i] = byte(rng.Intn(256))
	}
	return skel.UUID{UUID: uuid.UUID(bytes)}
}

func randomDecimal(rng *rand.Rand) skel.Decimal {
	return skel.NewDecimal(decimal.NewFromInt(int64(rng.Intn(10_000)) - 500))
}

var allStatuses = []order.OrderStatus{
	order.OrderStatusUnspecified,
	order.OrderStatusPending,
	order.OrderStatusPaid,
	order.OrderStatusCancelled,
}

func randomStatus(rng *rand.Rand) order.OrderStatus {
	return allStatuses[rng.Intn(len(allStatuses))]
}

func randomOrder(rng *rand.Rand) *order.Order {
	lineCount := rng.Intn(4)
	lines := make([]order.OrderLine, lineCount)
	for i := range lines {
		lines[i] = order.OrderLine{
			ProductId: randomUUID(rng),
			Quantity:  rng.Intn(20) + 1,
			UnitPrice: randomDecimal(rng),
		}
	}
	return &order.Order{
		Id: randomUUID(rng),
		Customer: identitypub.UserSummary{
			Id:          randomUUID(rng),
			DisplayName: "customer",
			Status:      identitypub.UserStatusActive,
		},
		Status: randomStatus(rng),
		Lines:  lines,
		// attributes 是契约中的必填成员：生成的 Validate 会拒绝 nil，
		// 所以随机构造器必须始终给出非 nil map。
		Attributes: map[string]string{},
		Receipt:    nil,
	}
}

// Lean: cancel_keeps_lines —— 取消不改动行项目。
func TestCancelKeepsLines(t *testing.T) {
	rng := rand.New(rand.NewSource(seed(t)))
	for i := 0; i < iterations; i++ {
		o := randomOrder(rng)
		if got := Cancel(o).Lines; !reflect.DeepEqual(got, o.Lines) {
			t.Fatalf("iter %d: cancel changed lines\n got %+v\nwant %+v", i, got, o.Lines)
		}
	}
}

// Lean: cancel_preserves_total —— 取消保持总额。
func TestCancelPreservesTotal(t *testing.T) {
	rng := rand.New(rand.NewSource(seed(t)))
	for i := 0; i < iterations; i++ {
		o := randomOrder(rng)
		if !Total(Cancel(o)).Equal(Total(o)) {
			t.Fatalf("iter %d: cancel changed total: got %s want %s", i, Total(Cancel(o)), Total(o))
		}
	}
}

// Lean: cancelled_is_terminal —— 已取消的订单再支付不会离开 CANCELLED。
func TestCancelledIsTerminal(t *testing.T) {
	rng := rand.New(rand.NewSource(seed(t)))
	for i := 0; i < iterations; i++ {
		o := randomOrder(rng)
		o.Status = order.OrderStatusCancelled
		if got := Pay(o).Status; got != order.OrderStatusCancelled {
			t.Fatalf("iter %d: pay escaped CANCELLED, status = %s", i, got)
		}
	}
}

// Lean: pay_paid_is_noop —— 已支付订单重复支付是幂等 no-op。
func TestPayPaidIsNoop(t *testing.T) {
	rng := rand.New(rand.NewSource(seed(t)))
	for i := 0; i < iterations; i++ {
		o := randomOrder(rng)
		o.Status = order.OrderStatusPaid
		if got := Pay(o); !reflect.DeepEqual(got, o) {
			t.Fatalf("iter %d: pay on PAID changed the order", i)
		}
	}
}

// Lean: step_only_from_pending —— 任何合法单步转移只能从 PENDING 出发。
// 状态空间有限（4×4），直接穷举，与 Lean 的有限分情况证明同构。
func TestStepOnlyFromPending(t *testing.T) {
	for _, from := range allStatuses {
		for _, to := range allStatuses {
			if CanStep(from, to) && from != order.OrderStatusPending {
				t.Fatalf("step %s -> %s allowed from non-PENDING state", from, to)
			}
		}
	}
}

// Lean: no_exit_from_cancelled —— CANCELLED 没有任何出边。
func TestNoExitFromCancelled(t *testing.T) {
	for _, to := range allStatuses {
		if CanStep(order.OrderStatusCancelled, to) {
			t.Fatalf("step CANCELLED -> %s must not be allowed", to)
		}
	}
}

// 契约的机器检查（第一层）：生成的 Validate 把「必填」约束变成运行时检查。
func TestGeneratedValidateAcceptsConstructedOrder(t *testing.T) {
	rng := rand.New(rand.NewSource(seed(t)))
	for i := 0; i < iterations; i++ {
		o := randomOrder(rng)
		if err := o.Validate(""); err != nil {
			t.Fatalf("iter %d: generated Validate rejected a constructed order: %v", i, err)
		}
	}
}

// 契约的机器检查（第二层）：JSON 编解码 round-trip 保持相等，
// 即生成的 wire format 与生成的类型一致（含枚举字符串编码）。
func TestJSONRoundTrip(t *testing.T) {
	rng := rand.New(rand.NewSource(seed(t)))
	for i := 0; i < iterations; i++ {
		o := randomOrder(rng)
		encoded, err := json.Marshal(o)
		if err != nil {
			t.Fatalf("iter %d: marshal: %v", i, err)
		}
		var decoded order.Order
		if err := json.Unmarshal(encoded, &decoded); err != nil {
			t.Fatalf("iter %d: unmarshal: %v\npayload: %s", i, err, encoded)
		}
		if !reflect.DeepEqual(&decoded, o) {
			t.Fatalf("iter %d: JSON round-trip changed the order\npayload: %s", i, encoded)
		}
	}
}
